const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define area between Elkhorn and Platte Rivers near Omaha
  const aoi = ee.Geometry.Polygon([[
    [-96.2, 41.1], [-96.0, 41.1], [-96.0, 41.3], [-96.2, 41.3], [-96.2, 41.1]
  ]]);

  // Function to mask clouds in Sentinel-2
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                 .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  // Function to calculate MNDWI
  function calculateMNDWI(image) {
    const mndwi = image.normalizedDifference(['B3', 'B11']).rename('MNDWI');
    return image.addBands(mndwi);
  }

  // Get March 2018 data
  const march2018 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(aoi)
    .filterDate('2018-03-01', '2018-03-31')
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20))
    .map(maskS2clouds)
    .map(calculateMNDWI)
    .median();

  // Get March 16, 2019 data
  const march16_2019 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(aoi)
    .filterDate('2019-03-16', '2019-03-16')
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20))
    .map(maskS2clouds)
    .map(calculateMNDWI)
    .median();

  // Check collection sizes
  const count2018 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(aoi)
    .filterDate('2018-03-01', '2018-03-31')
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20))
    .size();

  const count2019 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(aoi)
    .filterDate('2019-03-16', '2019-03-16')
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20))
    .size();

  const count2018Info = count2018.getInfo();
  const count2019Info = count2019.getInfo();

  console.log(`March 2018 Images: ${count2018Info} (Cloud<20%)`);
  console.log(`March 16, 2019 Images: ${count2019Info} (Cloud<20%)`);

  // Handle empty collections
  if (count2018Info === 0 || count2019Info === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Calculate water pixels (MNDWI > 0 indicates water)
  const water2018 = march2018.select('MNDWI').gt(0);
  const water2019 = march16_2019.select('MNDWI').gt(0);

  // Count water pixels
  const waterCount2018 = water2018.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: aoi,
    scale: 100,
    maxPixels: 1e9
  }).get('MNDWI');

  const waterCount2019 = water2019.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: aoi,
    scale: 100,
    maxPixels: 1e9
  }).get('MNDWI');

  const totalPixels2018 = water2018.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: aoi,
    scale: 100,
    maxPixels: 1e9
  }).get('MNDWI');

  const totalPixels2019 = water2019.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: aoi,
    scale: 100,
    maxPixels: 1e9
  }).get('MNDWI');

  const water2018Info = waterCount2018.getInfo();
  const water2019Info = waterCount2019.getInfo();
  const total2018Info = totalPixels2018.getInfo();
  const total2019Info = totalPixels2019.getInfo();

  console.log(`2018 Water Pixels: ${water2018Info}, Total: ${total2018Info}`);
  console.log(`2019 Water Pixels: ${water2019Info}, Total: ${total2019Info}`);

  // Check for no valid pixels
  if (total2018Info === 0 || total2019Info === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Check for calculation failures
  if (water2018Info === null || water2019Info === null || 
      isNaN(water2018Info) || isNaN(water2019Info)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Calculate water percentages
  const waterPercent2018 = (water2018Info / total2018Info * 100).toFixed(2);
  const waterPercent2019 = (water2019Info / total2019Info * 100).toFixed(2);

  console.log(`2018 Water: ${waterPercent2018}%`);
  console.log(`2019 Water: ${waterPercent2019}%`);

  // Determine if water extent increased
  if (water2019Info > water2018Info) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
